repo_files.pkce.py:
"""PKCE code challenge verification."""

import base64
import hashlib


class PKCEVerifier:
    @staticmethod
    def verify(verifier: str, challenge: str, method: str) -> bool:
        if method == "plain":
            return verifier == challenge
        elif method == "S256":
            # Compute SHA-256 and base64url encoding without padding
            digest = hashlib.sha256(verifier.encode("utf-8")).digest()
            encoded = base64.urlsafe_b64encode(digest).decode("utf-8").rstrip("=")
            return encoded == challenge
        return False

repo_files.token_store.py:
"""Issued access and refresh token storage."""

import uuid
from typing import Dict


class TokenStore:
    def __init__(self):
        self.tokens: Dict[str, str] = {}

    def issue(self, user_id: str, client_id: str) -> str:
        tok = f"access_{uuid.uuid4().hex}"
        self.tokens[tok] = user_id
        return tok

repo_files.exchange.py:
"""OAuth 2.0 Authorization code token exchange handler."""

from typing import Any, Dict, Optional
from auth_code import AuthCode
from pkce import PKCEVerifier
from token_store import TokenStore


class TokenExchangeHandler:
    def __init__(self, token_store: TokenStore):
        self.codes: Dict[str, AuthCode] = {}
        self.token_store = token_store

    def register_code(self, auth_code: AuthCode) -> None:
        self.codes[auth_code.code] = auth_code

    def exchange(self, client_id: str, code_str: str, code_verifier: str) -> Dict[str, Any]:
        code = self.codes.get(code_str)
        if not code:
            return {"error": "invalid_grant"}

        if code.client_id != client_id:
            return {"error": "invalid_client"}

        # BUG: Fails to check code.used or mark code.used = True,
        # allowing malicious attackers to replay authorization codes!
        if not PKCEVerifier.verify(code_verifier, code.code_challenge, code.code_challenge_method):
            return {"error": "invalid_grant"}

        access_token = self.token_store.issue(code.user_id, client_id)
        return {"access_token": access_token, "token_type": "Bearer"}

