"""OAuth 2.0 Authorization code token exchange handler."""

from typing import Any, Dict, Optional
from auth_code import AuthCode
from pkce import PKCEVerifier
from token_store import TokenStore


class TokenExchangeHandler:
    def __init__(self, token_store: TokenStore):
        self.codes: Dict[str, AuthCode] = {}
        self.token_store = token_store

    def register_code(self, auth_code: AuthCode) -> None:
        self.codes[auth_code.code] = auth_code

    def exchange(self, client_id: str, code_str: str, code_verifier: str) -> Dict[str, Any]:
        code = self.codes.get(code_str)
        if not code or code.used:
            return {"error": "invalid_grant"}

        if code.client_id != client_id:
            return {"error": "invalid_client"}

        # Invalidate code immediately upon first attempt
        code.used = True

        if not PKCEVerifier.verify(code_verifier, code.code_challenge, code.code_challenge_method):
            return {"error": "invalid_grant"}

        access_token = self.token_store.issue(code.user_id, client_id)
        return {"access_token": access_token, "token_type": "Bearer"}
